    return 'Échec : $error';
  }

  @override
  String failedToUpdateSignalLocationRadius(String error) {
    return 'Échec de la mise à jour du rayon de localisation du signal : $error';
  }

  @override
  String failedToSaveConfiguration(String error) {
    return 'Échec de l\'enregistrement de la configuration : $error';
  }

  @override
  String automationActionError(int index, String error) {
    return 'Action $index : $error';
  }

  @override
  String failedToPlay(String error) {
    return 'Échec de la lecture : $error';
  }

  @override
  String get whatsNewVersion190Subtitle => 'Version 1.9.0';

  @override
  String get whatsNewReachabilityTitle => 'Accessibilité';

  @override
  String get whatsNewReachabilityDescription => 'Estimez la probabilité d\'atteindre chaque noeud de votre mesh, sans envoyer le moindre paquet de test.\n\nL\'accessibilité observe passivement le trafic circulant dans le réseau et attribue une confiance Haute, Moyenne ou Faible à chaque noeud. Disponible dans le menu latéral sous Mesh.';

  @override
  String get whatsNewVersion1100Subtitle => 'Version 1.10.0';

  @override
  String get whatsNewWorldMapTitle => 'Carte mondiale';

  @override
  String get whatsNewWorldMapDescription => 'Visualisez l\'ensemble du réseau Meshtastic mondial sur une seule carte. Chaque point est un noeud partageant sa position : zoomez, déplacez-vous et appuyez pour explorer les détails des noeuds, les informations matérielles et les heures de dernière activité.\n\nAucune connexion requise. La carte mondiale extrait des données en direct depuis le backend SocialMesh afin que vous puissiez explorer le mesh n\'importe où.';

  @override
  String get whatsNewVersion1101Subtitle => 'Version 1.10.1';

  @override
  String get whatsNewPresenceTitle => 'Présence';

  @override
  String get whatsNewPresenceDescription => 'Voyez en un coup d\'oeil qui est actif sur votre mesh. Présence affiche l\'activité des noeuds en temps réel avec des indicateurs d\'intention : surveillance, mobilité ou station de base fixe.\n\nFiltrez par niveau d\'activité, recherchez par nom et appuyez sur n\'importe quel noeud pour voir son profil complet. Disponible dans le menu latéral sous Social.';

  @override
  String get whatsNewVersion1110Subtitle => 'Version 1.11.0';

  @override
  String get whatsNewSignalsTitle => 'Signals';

  @override
  String get whatsNewSignalsDescription => 'Diffusez des moments éphémères sur votre mesh. Les Signals sont des publications de courte durée : partagez du texte, une photo ou votre position avec une durée de vie de 15 minutes à 24 heures.\n\nLes signaux à proximité apparaissent en premier avec des badges de proximité indiquant le nombre de sauts. Lorsqu\'ils expirent, ils disparaissent. Du contenu véritablement hors ligne et éphémère.';

  @override
  String get whatsNewVersion1130Subtitle => 'Version 1.13.0';

  @override
  String get whatsNewNodeDexTitle => 'NodeDex';

  @override
  String get whatsNewNodeDexDescription => 'Un journal de terrain vivant du monde mesh. Chaque noeud découvert est automatiquement enregistré avec un Sigil procédural unique et un trait de personnalité dérivé du comportement réel.\n\nDisponible dans le menu latéral sous Social. Filtrez par trait, recherchez par nom ou ID hexadécimal, et appuyez sur n\'importe quelle entrée pour explorer son profil complet : historique du signal, chronologie de découverte, et plus encore.';

  @override
  String get whatsNewVersion1150Subtitle => 'Version 1.15.0';

  @override
  String get whatsNewAetherTitle => 'Aether';

  @override
  String get whatsNewAetherDescription => 'Suivez les noeuds Meshtastic en altitude ! Planifiez votre vol avec votre noeud mesh et laissez les stations au sol du monde entier capter votre signal.\n\nÀ 10 000 m, LoRa peut atteindre plus de 400 km. Signalez les réceptions, rivalisez sur le classement de distance et établissez de nouveaux records de portée. Disponible dans le menu latéral sous Social.';

  @override
  String get whatsNewVersion1160Subtitle => 'Version 1.16.0';

  @override
  String get whatsNewTakGatewayTitle => 'Passerelle TAK';

  @override
  String get whatsNewTakGatewayDescription => 'Intégrez votre mesh dans l\'écosystème Team Awareness Kit (TAK). SocialMesh se connecte désormais à une passerelle TAK via WebSocket et diffuse en direct les entités Cursor-on-Target sur votre carte.\n\nChaque entité est colorée selon l\'affiliation standard et dotée d\'une icône spécifique à sa dimension. Filtrez par affiliation, recherchez des indicatifs, suivez des entités par appui long et appuyez sur n\'importe quel marqueur pour obtenir les détails CoT complets. Disponible dans le menu latéral sous Mesh.';

  @override
  String get whatsNewVersion1270Subtitle => 'Version 1.27.0';

  @override
  String get whatsNewTranslationPackTitle => 'Pack Traduction';

  @override
  String get whatsNewTranslationPackDescription => 'Traduisez n\'importe quel message mesh à la demande avec mise en cache intelligente et contrôles de confidentialité. Comprend une allocation de traduction gérée, ou utilisez votre propre clé API OpenAI pour un usage étendu.\n\nAppuyez longuement sur n\'importe quel message et appuyez sur Traduire pour voir le résultat en ligne, avec mise en cache intelligente pour des traductions répétées instantanées. Désormais inclus dans le Pack Complet.';

  @override
  String get notificationNewNodeTitle => 'Nouveau nœud découvert';

  @override
  String notificationNewNodeBody(String nodeName, String shortCode) {
    return '$nodeName ($shortCode) a rejoint le mesh';
  }

  @override
  String notificationBatchedNodesTitle(int count) {
    String _temp0 = intl.Intl.pluralLogic(
      count,
      locale: localeName,
      other: '$count nouveaux nœuds découverts',
      one: '1 nouveau nœud découvert',
    );
    return '$_temp0';
  }

